const email = String($json.email ?? '').trim().toLowerCase();
const customerId = String($json.customer_id ?? '').trim().toUpperCase();

if (!email && !customerId) {
  throw new Error('Provide email or customer_id');
}
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('email is invalid');
}
if (customerId && !/^[A-Z0-9][A-Z0-9_-]{1,63}$/.test(customerId)) {
  throw new Error('customer_id is invalid');
}

return { json: { email, customer_id: customerId, started_at_ms: Date.now() } };

const input = $('Validate Customer Lookup').first().json;
const row = $json ?? {};
const customer = row.customer_id ? {
  customer_id: row.customer_id,
  first_name: row.first_name,
  last_name: row.last_name,
  email: row.email,
  phone: row.phone ?? null,
  preferred_contact_method: row.preferred_contact_method,
  customer_since: row.customer_since,
  account_type: row.account_type,
  account_status: row.account_status,
  created_at: row.created_at,
  updated_at: row.updated_at
} : null;

if (customer && input.email && String(customer.email).toLowerCase() !== input.email) {
  throw new Error('email and customer_id identify different customers');
}

return { json: {
  input,
  customer,
  lookup_email: customer?.email ?? input.email ?? 'no-match@invalid.local'
} };

const prepared = $('Prepare HubSpot Lookup').first().json;
const customer = prepared.customer;
const response = $input.first().json ?? {};
const matches = Array.isArray(response.results) ? response.results : [];

if (matches.length > 1) {
  throw new Error(`HubSpot returned ${matches.length} contacts for one email`);
}

const contact = matches[0] ?? null;
const hp = contact?.properties ?? {};
const mismatches = [];
if (customer && contact) {
  const checks = [
    ['customer_id', customer.customer_id, hp.customer_id],
    ['email', String(customer.email).toLowerCase(), String(hp.email ?? '').toLowerCase()],
    ['first_name', customer.first_name, hp.firstname],
    ['last_name', customer.last_name, hp.lastname],
    ['phone', customer.phone ?? '', hp.phone ?? ''],
    ['preferred_contact_method', customer.preferred_contact_method, hp.preferred_contact_method],
    ['customer_since', String(customer.customer_since).slice(0, 10), String(hp.customer_since ?? '').slice(0, 10)],
    ['account_type', customer.account_type, hp.account_type]
  ];
  for (const [field, left, right] of checks) {
    if (String(left ?? '') !== String(right ?? '')) mismatches.push(field);
  }
}

let consistency = 'matched';
if (!customer && contact) consistency = 'supabase_missing';
else if (customer && !contact) consistency = 'hubspot_missing';
else if (!customer && !contact) consistency = 'not_found';
else if (mismatches.length) consistency = 'mismatch';

return [{ json: {
  found: Boolean(customer),
  customer,
  hubspot: {
    found: Boolean(contact),
    contact_id: contact?.id ?? null,
    properties: contact ? hp : null
  },
  data_consistency: consistency,
  mismatched_fields: mismatches,
  latency_ms: Date.now() - prepared.input.started_at_ms
} }];
